DDL = "\nCREATE TABLE cehub_ai.ai_issue_event_receipts (\n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tevent_row_id BIGINT NOT NULL, \n\toperation_key VARCHAR(80) NOT NULL, \n\tsource_digest VARCHAR(64), \n\trun_id UUID, \n\tprincipal_id UUID, \n\tstatus VARCHAR(20) NOT NULL, \n\treason VARCHAR(80) NOT NULL, \n\treceipt JSONB NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tCONSTRAINT pk_ai_issue_event_receipts PRIMARY KEY (id), \n\tCONSTRAINT fk_ai_issue_event_receipts_tenant_id_projects FOREIGN KEY(tenant_id, project_id) REFERENCES cehub_project.projects (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_ai_issue_event_receipts_tenant_id_events FOREIGN KEY(tenant_id, event_row_id) REFERENCES cehub_event.events (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_ai_issue_event_receipts_tenant_id_agent_runs FOREIGN KEY(tenant_id, run_id) REFERENCES cehub_ai.agent_runs (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_ai_issue_event_receipts_tenant_id_ai_principals FOREIGN KEY(tenant_id, principal_id) REFERENCES cehub_ai.ai_principals (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT ck_ai_issue_event_receipts_shape CHECK (operation_key='event.issue.create' AND event_row_id>0 AND status IN ('queued','reused','skipped') AND btrim(reason)<>'' AND (source_digest IS NULL OR source_digest ~ '^[a-f0-9]{64}$') AND ((status='skipped' AND run_id IS NULL) OR (status IN ('queued','reused') AND run_id IS NOT NULL AND source_digest IS NOT NULL AND principal_id IS NOT NULL)) AND (jsonb_typeof(receipt)='object' AND receipt->>'version'='issue-event-receipt.v1' AND receipt->>'consumer_key'='issue_creation_events_v1' AND receipt->>'event_row_id'=event_row_id::text AND receipt->>'operation_key'=operation_key AND receipt->>'status'=status AND receipt->>'reason'=reason AND btrim(receipt->>'message')<>'' AND (receipt->>'created_at')::timestamptz=created_at) IS TRUE), \n\tCONSTRAINT uq_ai_issue_event_operation UNIQUE (tenant_id, event_row_id, operation_key)\n)\n\n"

GUARD = "CREATE FUNCTION cehub_ai.guard_issue_event_receipt() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n IF NOT EXISTS(SELECT 1 FROM cehub_event.events e\n  WHERE e.tenant_id=NEW.tenant_id AND e.project_id=NEW.project_id AND e.id=NEW.event_row_id\n   AND e.event_type IN ('TEST_FAILED','NPI_RECORD_CHANGED')\n   AND e.event_id=NEW.receipt->>'event_id' AND e.timestamp<=NEW.created_at)\n THEN RAISE EXCEPTION 'Issue event receipt requires its original scoped event'; END IF;\n IF NEW.status='skipped' THEN\n  IF COALESCE(NEW.receipt->'run'->>'run_id','')<>'' THEN\n   RAISE EXCEPTION 'Skipped Issue event receipt cannot reference a run';\n  END IF;\n  RETURN NEW;\n END IF;\n IF NOT EXISTS(\n  SELECT 1 FROM cehub_ai.agent_runs r\n  JOIN cehub_event.events e ON e.tenant_id=r.tenant_id AND e.project_id=r.project_id\n  JOIN cehub_audit.audit_log a ON a.tenant_id=e.tenant_id AND a.project_id=e.project_id\n   AND a.event_id=e.event_id AND a.entity=e.entity AND a.entity_id=e.entity_id\n   AND a.timestamp=e.timestamp\n  JOIN cehub_ai.ai_write_policies p ON p.tenant_id=r.tenant_id\n   AND p.id::text=r.run_context->'issue_event_trigger'->>'policy_id'\n  JOIN cehub_ai.ai_write_scope_revisions s ON s.tenant_id=r.tenant_id\n   AND s.project_id=r.project_id AND s.id::text=r.run_context->'issue_event_trigger'->>'scope_revision_id'\n  WHERE r.tenant_id=NEW.tenant_id AND r.project_id=NEW.project_id AND r.id=NEW.run_id\n   AND r.agent_key='quality_intelligence' AND r.context_version='event-issue-request-v1'\n   AND r.subscription_id IS NULL AND r.event_count=0 AND r.event_row_ids='[]'::jsonb\n   AND r.requested_by_user_id=a.actor_user_id AND a.actor_user_id IS NOT NULL\n   AND r.created_at>=e.timestamp AND r.created_at<=NEW.created_at\n   AND (NEW.status='reused' OR r.status='queued')\n   AND e.id=NEW.event_row_id AND e.event_id=NEW.receipt->>'event_id'\n   AND ((e.event_type='TEST_FAILED' AND e.source='quality_service' AND e.entity='test'\n      AND e.payload->>'test_record_id'=e.entity_id::text AND a.action='npi.test_case.failed')\n    OR (e.event_type='NPI_RECORD_CHANGED' AND e.source='npi_service' AND e.entity='npi_record'\n      AND e.payload->>'record_type'='material_exception'\n      AND e.payload->>'action' IN ('confirmed','reviewed')\n      AND a.action='npi.material_exception.'||(e.payload->>'action')))\n   AND p.principal_id=NEW.principal_id AND p.mode='tiered'\n   AND p.contract_version='dc11-write-policy.v1'\n   AND p.operation_settings->'event.issue.create'->>'mode'='automatic'\n   AND s.principal_id=NEW.principal_id AND s.operation_key='event.issue.create' AND s.enabled\n   AND e.timestamp>=p.created_at AND e.timestamp>=s.created_at\n   AND r.run_context->'issue_event_trigger'->>'version'='issue-event.v1'\n   AND r.run_context->'issue_event_trigger'->>'event_row_id'=e.id::text\n   AND r.run_context->'issue_event_trigger'->>'event_id'=e.event_id\n   AND r.run_context->'issue_event_trigger'->>'actor_user_id'=a.actor_user_id::text\n   AND r.run_context->'issue_event_trigger'->>'principal_id'=NEW.principal_id::text\n   AND r.run_context->'issue_event_trigger'->>'source_digest'=NEW.source_digest\n   AND r.run_context->'issue_event_source'->>'tenant_id'=NEW.tenant_id::text\n   AND r.run_context->'issue_event_source'->>'project_id'=NEW.project_id::text\n   AND r.run_context->'issue_event_source'->>'event_row_id'=e.id::text\n   AND r.run_context->'issue_event_source'->>'event_id'=e.event_id\n   AND r.run_context->'issue_event_source'->>'event_type'=e.event_type\n   AND r.run_context->'issue_event_source'->>'entity_id'=e.entity_id::text\n   AND r.run_context->'issue_event_source'->>'source_digest'=NEW.source_digest\n   AND NEW.receipt->'source'->>'audit_row_id'=a.id::text\n   AND NEW.receipt->'source'->>'actor_user_id'=a.actor_user_id::text\n   AND NEW.receipt->'source'->>'policy_id'=p.id::text\n   AND NEW.receipt->'source'->>'scope_revision_id'=s.id::text\n   AND NEW.receipt->'source'->>'principal_id'=NEW.principal_id::text\n   AND NEW.receipt->'source'->>'source_digest'=NEW.source_digest\n   AND NEW.receipt->'run'->>'run_id'=NEW.run_id::text\n   AND NEW.receipt->'run'->>'source_digest'=NEW.source_digest\n   AND NEW.receipt->'run'->'reused'=to_jsonb(NEW.status='reused')\n ) THEN RAISE EXCEPTION 'Issue event receipt requires exact original actor, source and authorized run'; END IF;\n RETURN NEW;\nEND $$;\nCREATE TRIGGER guard_issue_event_receipt BEFORE INSERT ON cehub_ai.ai_issue_event_receipts\n FOR EACH ROW EXECUTE FUNCTION cehub_ai.guard_issue_event_receipt();\nCREATE TRIGGER immutable_ai_issue_event_receipts BEFORE UPDATE OR DELETE ON cehub_ai.ai_issue_event_receipts\n FOR EACH ROW EXECUTE FUNCTION cehub_ai.protect_checkpoint_history();\nREVOKE ALL ON cehub_ai.ai_issue_event_receipts FROM PUBLIC;\nDO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='pdos_agent') THEN\n REVOKE ALL ON cehub_ai.ai_issue_event_receipts FROM pdos_agent; END IF; END $$;\n"


